// Parse the Resend contact form email
const items = $input.all();
const results = [];

for (const item of items) {
  const subject = item.json.subject || '';
  const body = item.json.textPlain || item.json.snippet || '';
  const htmlBody = item.json.textHtml || '';
  const fromEmail = item.json.from?.value?.[0]?.address || item.json.from || '';
  const messageId = item.json.messageId || '';
  const threadId = item.json.threadId || '';

  // Parse subject: "New support request from Jane Doe (seeker)"
  const subjectMatch = subject.match(/New support request from (.+?) \((seeker|owner)\)/i);
  const senderName = subjectMatch ? subjectMatch[1].trim() : 'User';
  const senderRole = subjectMatch ? subjectMatch[2].toLowerCase() : 'seeker';

  // Parse HTML body for structured fields
  // Format: <p><strong>Name:</strong> Jane Doe</p>
  //         <p><strong>Email:</strong> jane@example.com</p>
  //         <p><strong>Role:</strong> seeker</p>
  //         <p><strong>Message:</strong></p><p>...</p>

  let parsedName = senderName;
  let parsedEmail = '';
  let parsedRole = senderRole;
  let parsedMessage = '';

  // Try HTML parsing first
  const nameMatch = htmlBody.match(/<strong>Name:<\/strong>\s*([^<]+)/i);
  if (nameMatch) parsedName = nameMatch[1].trim();

  const emailMatch = htmlBody.match(/<strong>Email:<\/strong>\s*([^<]+)/i);
  if (emailMatch) parsedEmail = emailMatch[1].trim();

  const roleMatch = htmlBody.match(/<strong>Role:<\/strong>\s*([^<]+)/i);
  if (roleMatch) parsedRole = roleMatch[1].trim();

  const messageMatch = htmlBody.match(/<strong>Message:<\/strong>\s*<\/p>\s*<p>([\s\S]*?)<\/p>/i);
  if (messageMatch) parsedMessage = messageMatch[1].trim();

  // Fallback: parse plain text body
  if (!parsedEmail) {
    const textEmailMatch = body.match(/Email:\s*(.+)/i);
    if (textEmailMatch) parsedEmail = textEmailMatch[1].trim();
  }
  if (!parsedMessage) {
    const textMsgMatch = body.match(/Message:\s*([\s\S]+)/i);
    if (textMsgMatch) parsedMessage = textMsgMatch[1].trim();
  }

  // Clean up role display
  const roleDisplay = parsedRole === 'owner' ? 'Property Owner' : 'Room Seeker';

  // Create issue summary (first 50 chars)
  const issueSummary = parsedMessage.length > 50 
    ? parsedMessage.substring(0, 50) + '...' 
    : parsedMessage;

  // Generate smart personalized response based on role and keywords
  let personalizedResponse = '';
  const msgLower = parsedMessage.toLowerCase();

  if (msgLower.includes('login') || msgLower.includes('sign in') || msgLower.includes('password') || msgLower.includes('access')) {
    personalizedResponse = `I can see you're having trouble accessing your account. Here are a few things to try:\n\n1. Clear your browser cache and try signing in again\n2. Use the "Forgot Password" option on the login page\n3. Make sure you're using the same email you registered with\n\nIf the issue persists, I can look into your account directly.`;
  } else if (msgLower.includes('payment') || msgLower.includes('pay') || msgLower.includes('charge') || msgLower.includes('refund') || msgLower.includes('billing')) {
    personalizedResponse = `I understand you have a billing-related concern. I'll review your account details and get back to you with a resolution within 24 hours.\n\nIn the meantime, please don't hesitate to share any relevant transaction IDs or screenshots.`;
  } else if (msgLower.includes('listing') || msgLower.includes('property') || msgLower.includes('room') || msgLower.includes('post')) {
    if (parsedRole === 'owner') {
      personalizedResponse = `I'll help you with your property listing. As a property owner, you can manage your listings from your dashboard.\n\nIf you're having trouble creating or editing a listing, I'd be happy to walk you through the process or make changes on your end.`;
    } else {
      personalizedResponse = `I'll help you find what you're looking for. Our platform has a range of listings that might suit your needs.\n\nYou can refine your search using filters on the listings page, or let me know your preferences and I can point you in the right direction.`;
    }
  } else if (msgLower.includes('bug') || msgLower.includes('error') || msgLower.includes('broken') || msgLower.includes('not working') || msgLower.includes('issue')) {
    personalizedResponse = `Thanks for reporting this issue. I've noted the details and our team will investigate.\n\nCould you let me know:\n- What device/browser you're using\n- When the issue first occurred\n- Any error messages you saw\n\nThis will help us resolve it faster.`;
  } else if (msgLower.includes('verify') || msgLower.includes('verification') || msgLower.includes('id') || msgLower.includes('identity')) {
    personalizedResponse = `I understand you have a question about verification. Our verification process helps keep the community safe for everyone.\n\nI'll review your verification status and follow up with next steps.`;
  } else if (msgLower.includes('message') || msgLower.includes('chat') || msgLower.includes('contact') || msgLower.includes('reply')) {
    personalizedResponse = `I'll look into your messaging concern. You can access your messages from your dashboard or the messages page.\n\nIf you're having trouble reaching another user, let me know and I can help.`;
  } else {
    personalizedResponse = `I've reviewed your message and I'll look into this for you. I'll follow up with more details shortly.\n\nIf you have any additional information to share, feel free to reply to this email.`;
  }

  results.push({
    json: {
      senderName: parsedName,
      senderEmail: parsedEmail,
      senderRole: parsedRole,
      roleDisplay: roleDisplay,
      message: parsedMessage,
      issueSummary: issueSummary,
      personalizedResponse: personalizedResponse,
      originalSubject: subject,
      originalMessageId: messageId,
      threadId: threadId,
      receivedAt: new Date().toISOString()
    }
  });
}

return results;

// Format notification message
const item = $input.first();
const data = item.json;

const now = new Date();
const timeStr = now.toLocaleString('en-AU', { timeZone: 'Australia/Melbourne' });

return [{
  json: {
    notificationSubject: `📬 Draft ready: ${data.senderName} (${data.roleDisplay})`,
    notificationBody: `A Gmail draft has been created for a support request.\n\n👤 From: ${data.senderName} (${data.senderEmail})\n🏷️ Role: ${data.roleDisplay}\n💬 Issue: ${data.issueSummary}\n⏰ Received: ${timeStr}\n\nOpen Gmail to review and send the draft.`,
    senderName: data.senderName,
    senderEmail: data.senderEmail,
    roleDisplay: data.roleDisplay,
    issueSummary: data.issueSummary
  }
}];

